$ErrorActionPreference = 'Stop'; Push-Location 'c:\git\semio'; $script = @'
import { chromium } from "playwright";
import { readFile } from "node:fs/promises";
import { importKit as importKitArchive } from "./semio/js/index.ts";
const zipBytes = await readFile("C:/git/semio/semio/assets/semio/metabolism.zip");
const { kit } = await importKitArchive(new Uint8Array(zipBytes));
const browser = await chromium.launch({
  headless: true,
  args: ["--use-angle=swiftshader", "--enable-unsafe-swiftshader"],
});
const page = await browser.newPage();
page.on("console", (msg) => console.log("[console]", msg.type(), msg.text()));
page.on("pageerror", (err) => console.log("[pageerror]", err.stack || err.message));
try {
  await page.goto("http://127.0.0.1:4181/", { waitUntil: "commit" });
  await page.waitForTimeout(2000);
  const created = await page.evaluate(async (kitArg) => {
    const store = window.__SEMIO_STORE__;
    return await store.execute("semio.sketchpad.createKit", "semio.sketchpad.test.ensureMetabolismKitLoaded", kitArg, false, false);
  }, kit);
  console.log("CREATED", JSON.stringify(created));
  const row = page.locator("tr[data-row-id]").filter({ hasText: /metabolism/i }).first();
  console.log("ROW_VISIBLE", await row.isVisible().catch(() => false));
  if (await row.isVisible().catch(() => false)) {
    await row.click({ force: true });
    console.log("CLICKED_ROW");
  }
  await page.evaluate((kitId) => {
    const navigate = window.__SEMIO_NAVIGATE__;
    if (typeof navigate !== "function") throw new Error("missing navigate bridge");
    navigate(`/kits/${kitId}`);
  }, created.kitId);
  let previous = 0;
  for (const mark of [2000, 5000, 10000, 20000, 30000, 40000]) {
    await page.waitForTimeout(mark - previous);
    previous = mark;
    const state = await page.evaluate(() => ({
      hasTbody: !!document.querySelector("tbody"),
      tbodyCount: document.querySelectorAll("tbody").length,
      rowCount: document.querySelectorAll("[data-row-id]").length,
      canvasCount: document.querySelectorAll("canvas").length,
      bodyText: document.body.textContent?.slice(0, 500),
      failed: document.body.textContent?.includes("Failed to load kit app") ?? false,
      loadingApps: document.body.textContent?.includes("Loading apps") ?? false,
      loadingKit: document.body.textContent?.includes("Loading kit") ?? false,
    }));
    console.log("STATE", mark, JSON.stringify(state));
  }
} finally {
  await browser.close();
}
